CREATE TRIGGER audit_users_insert AFTER INSERT ON users BEGIN
INSERT INTO audit_logs(request_id,actor_id,actor_name,actor_role,action,entity,entity_id,before_json,after_json,reason,operation,created_at)
VALUES ((SELECT request_id FROM audit_context WHERE id=1),(SELECT actor_id FROM audit_context WHERE id=1),COALESCE((SELECT actor_name FROM audit_context WHERE id=1),'Hệ thống / ngoài ứng dụng'),COALESCE((SELECT actor_role FROM audit_context WHERE id=1),'system'),'insert','users',NEW.id,NULL,json_object('id',NEW.id,'name',NEW.name,'email',NEW.email,'role',NEW.role,'birth_date',NEW.birth_date,'deleted_at',NEW.deleted_at,'points',NEW.points,'lifetime_points',NEW.lifetime_points,'created_at',NEW.created_at),COALESCE((SELECT reason FROM audit_context WHERE id=1),''),COALESCE((SELECT operation FROM audit_context WHERE id=1),'Database change'),strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
--> statement-breakpoint
CREATE TRIGGER audit_users_update AFTER UPDATE ON users WHEN OLD.id IS NOT NEW.id OR OLD.name IS NOT NEW.name OR OLD.email IS NOT NEW.email OR OLD.role IS NOT NEW.role OR OLD.birth_date IS NOT NEW.birth_date OR OLD.deleted_at IS NOT NEW.deleted_at OR OLD.points IS NOT NEW.points OR OLD.lifetime_points IS NOT NEW.lifetime_points OR OLD.created_at IS NOT NEW.created_at OR OLD.password_hash IS NOT NEW.password_hash BEGIN
